for _name, _fn in _HTTPMethodsMixin.__dict__.items():
    if _name.startswith("_"):
        continue
    if _name in _RESERVED:
        continue
    if not callable(_fn):
        continue
    setattr(VibeBotHTTP, _name, _fn)
